import React, { useMemo } from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring } from '../remotionShim';
import { evolvePath, getLength, getPointAtLength } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceFamily } = loadSpaceGrotesk();



export type MapJourneyProps = Record<string, any>;

const mapPath = "M 0 0 C 300 -200, 600 300, 1000 100 S 1800 -300, 2200 0 S 3000 400, 3500 0";

const IconSVG = ({ type }: { type: string }) => {
  if (type === "script")
    return (
      <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
        <polyline points="14 2 14 8 20 8" />
        <line x1="16" y1="13" x2="8" y2="13" />
        <line x1="16" y1="17" x2="8" y2="17" />
        <polyline points="10 9 9 9 8 9" />
      </svg>
    );
  if (type === "location")
    return (
      <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z" />
        <circle cx="12" cy="10" r="3" />
      </svg>
    );
  if (type === "camera")
    return (
      <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z" />
        <circle cx="12" cy="13" r="3" />
      </svg>
    );
  if (type === "editing")
    return (
      <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="6" cy="6" r="3" />
        <circle cx="6" cy="18" r="3" />
        <line x1="20" y1="4" x2="8.12" y2="15.88" />
        <line x1="14.47" y1="14.48" x2="20" y2="20" />
        <line x1="8.12" y1="8.12" x2="12" y2="12" />
      </svg>
    );
  return null;
};

const MapJourney: React.FC<MapJourneyProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 15,
  pathColor = "#81a969",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const f3s = 3 * fps;
  const f6s = 6 * fps;
  const f9s = 9 * fps;
  const f13s = 13 * fps;

  const pathLength = useMemo(() => {
    try {
      return getLength(mapPath);
    } catch (e) {
      return 3500;
    }
  }, []);

  const drawProgress = interpolate(frame, [0, f3s, f6s, f9s], [0, 0.15, 0.4, 1.0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const cameraProgress = interpolate(frame, [0, f3s, f6s, f9s], [0, 0.0, 0.3, 1.0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  let evolution = { strokeDasharray: "10000 10000", strokeDashoffset: 10000 };
  try {
    evolution = evolvePath(Math.max(0.0001, drawProgress), mapPath);
  } catch (err) {
    // fallback to static path if parsed wrong
  }

  const currentCameraPoint = useMemo(() => {
    try {
      return getPointAtLength(mapPath, cameraProgress * pathLength);
    } catch (e) {
      return { x: 0, y: 0 };
    }
  }, [cameraProgress, pathLength]);

  const endPoint = useMemo(() => {
    try {
      return getPointAtLength(mapPath, pathLength);
    } catch (e) {
      return { x: 3500, y: 0 };
    }
  }, [pathLength]);

  const transitionPan = interpolate(frame, [f13s, f13s + 60], [0, -width * 1.5], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const mapX = width / 2 - currentCameraPoint.x + transitionPan;
  const mapY = height / 2 - currentCameraPoint.y;

  // Animations Start Node
  const startScale = spring({ frame, fps, config: { damping: 12 } });
  const shootOpacity = interpolate(frame, [15, 30], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Route Icons
  const routeIcons = [
    { progress: 0.05, frame: f3s + 15, type: "script", label: "Scripting" },
    { progress: 0.12, frame: f3s + 36, type: "location", label: "Location" },
    { progress: 0.20, frame: f3s + 60, type: "camera", label: "Shooting" },
    { progress: 0.28, frame: f3s + 84, type: "editing", label: "Editing" },
  ];

  // Screen Effects F180-F270
  const speedLinesOpacity = interpolate(frame, [f6s, f6s + 10, f9s - 10, f9s], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const laterOpacity = interpolate(frame, [f6s, f6s + 15, f9s - 15, f9s], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const laterScale = interpolate(frame, [f6s, f9s], [0.9, 1.1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Animations End Node F270+
  const endNodeScale = spring({ frame: frame - f9s, fps, config: { damping: 14 } });
  const text31Scale = spring({ frame: frame - (f9s + 10), fps, config: { damping: 10, mass: 1.5 } });
  const profOpacity = interpolate(frame, [f9s + 40, f9s + 60], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const readyOpacity = interpolate(frame, [f9s + 70, f9s + 90], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const tileCoords = useMemo(() => {
    const coords = [];
    for (let r = -2; r <= 2; r++) {
      for (let c = -4; c <= 4; c++) {
        if (Math.abs(r) <= 1 && Math.abs(c) <= 1) continue;
        coords.push({ c, r });
      }
    }
    return coords.slice(0, 31);
  }, []);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden", transition: "none" }}>
      {/* Map Content Layer */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          transform: `translate(${mapX}px, ${mapY}px)`,
          transition: "none",
        }}
      >
        {/* Map Grid Pattern */}
        <div
          style={{
            position: "absolute",
            top: -3000,
            left: -3000,
            width: 10000,
            height: 10000,
            backgroundImage: `radial-gradient(${textColor}15 2px, transparent 2px)`,
            backgroundSize: "50px 50px",
            transition: "none",
          }}
        />

        {/* Drawn Path */}
        <svg width="1" height="1" style={{ position: "absolute", top: 0, left: 0, overflow: "visible", filter: `drop-shadow(0px 0px 8px ${pathColor}80)` }}>
          <path
            d={mapPath}
            stroke={pathColor}
            strokeWidth={8}
            fill="none"
            strokeDasharray={evolution.strokeDasharray}
            strokeDashoffset={evolution.strokeDashoffset}
            strokeLinecap="round"
            style={{ transition: "none" }}
          />
        </svg>

        {/* Start Point */}
        <div style={{ position: "absolute", left: 0, top: 0, transform: `translate(-50%, -50%) scale(${startScale})`, zIndex: 10, transition: "none" }}>
          <div style={{ width: 44, height: 44, backgroundColor: bgColor, borderRadius: "50%", border: `4px solid ${pathColor}`, boxShadow: `0 0 15px ${pathColor}` }} />
          <div style={{ position: "absolute", top: 60, left: "50%", transform: "translateX(-50%)", whiteSpace: "nowrap", opacity: shootOpacity, transition: "none" }}>
            <div style={{ fontSize: 36, fontWeight: "bold", color: textColor, fontFamily: spaceFamily }}>3 Hour Shoot</div>
          </div>
        </div>

        {/* Pop-up Icons */}
        {routeIcons.map((icon, i) => {
          let p = { x: 0, y: 0 };
          try {
            p = getPointAtLength(mapPath, icon.progress * pathLength);
          } catch (e) {}
          const scale = spring({ frame: frame - icon.frame, fps, config: { damping: 10 } });
          return (
            <div key={i} style={{ position: "absolute", left: p.x, top: p.y, transform: `translate(-50%, -50%) scale(${scale})`, transition: "none", zIndex: 12 }}>
              <div
                style={{
                  width: 60,
                  height: 60,
                  backgroundColor: "#111",
                  borderRadius: "50%",
                  border: `3px solid ${pathColor}`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  color: pathColor,
                  boxShadow: `0 0 20px ${pathColor}40`,
                }}
              >
                <IconSVG type={icon.type} />
              </div>
            </div>
          );
        })}

        {/* Final Destination Node */}
        <div style={{ position: "absolute", left: endPoint.x, top: endPoint.y, transform: `translate(-50%, -50%)`, transition: "none", zIndex: 5 }}>
          <div
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              transform: `translate(-50%, -50%) scale(${endNodeScale})`,
              width: 800,
              height: 800,
              borderRadius: "50%",
              backgroundColor: `${pathColor}0a`,
              border: `2px dashed ${pathColor}40`,
              transition: "none",
            }}
          />

          {/* Video Tiles Grid */}
          <div style={{ position: "absolute", top: 0, left: 0, width: 0, height: 0 }}>
            {tileCoords.map((coord, i) => {
              const tileF = frame - (f9s + 20) - i * 1.5;
              const scale = spring({ frame: tileF, fps, config: { damping: 12 } });
              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: coord.c * 100,
                    top: coord.r * 150,
                    width: 70,
                    height: 120,
                    transform: `translate(-50%, -50%) scale(${scale})`,
                    backgroundColor: "#1a1a1a",
                    borderRadius: 8,
                    border: `1px solid ${pathColor}80`,
                    boxShadow: "0 4px 12px rgba(0,0,0,0.4)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    zIndex: 0,
                    transition: "none",
                  }}
                >
                  <svg width="24" height="24" viewBox="0 0 24 24" fill={pathColor}>
                    <polygon points="5 3 19 12 5 21 5 3" />
                  </svg>
                </div>
              );
            })}
          </div>

          {/* Central Text */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              transform: "translate(-50%, -50%)",
              zIndex: 10,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              transition: "none",
            }}
          >
            <div style={{ fontSize: 180, fontWeight: 900, fontFamily: spaceFamily, color: "#fff", transform: `scale(${text31Scale})`, lineHeight: 1, textShadow: "0 8px 30px rgba(0,0,0,0.8)", transition: "none" }}>
              31
            </div>
            <div style={{ fontSize: 36, color: pathColor, fontWeight: "bold", opacity: profOpacity, marginTop: -10, transition: "none" }}>Professional Videos</div>
          </div>

          <div
            style={{
              position: "absolute",
              top: 380,
              left: 0,
              transform: "translate(-50%, -50%)",
              width: 800,
              textAlign: "center",
              zIndex: 10,
              opacity: readyOpacity,
              transition: "none",
            }}
          >
            <div style={{ fontSize: 32, color: textColor, opacity: 0.7 }}>Ready to post across all social platforms</div>
          </div>
        </div>
      </div>

      {/* Screen Space Overlays */}
      <div style={{ position: "absolute", inset: 0, opacity: speedLinesOpacity, pointerEvents: "none", zIndex: 15, transition: "none" }}>
        {Array.from({ length: 15 }).map((_, i) => {
          const top = (i * 97) % height;
          const speed = (i % 3) * 20 + 50;
          const length = (i % 5) * 150 + 200;
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                top,
                left: width - ((frame * speed + i * 300) % (width + length)),
                width: length,
                height: 3,
                backgroundColor: "rgba(255, 255, 255, 0.5)",
                boxShadow: "0 0 10px rgba(255,255,255,0.8)",
                transition: "none",
              }}
            />
          );
        })}
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: laterOpacity,
          transform: `scale(${laterScale})`,
          zIndex: 20,
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <div style={{ fontSize: 96, fontWeight: 900, fontStyle: "italic", fontFamily: spaceFamily, color: "#fff", textShadow: "0 4px 30px rgba(0,0,0,0.9)", transition: "none" }}>
          48 Hours Later...
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MapJourney;